+        path.reset();
+        return;
+      }

-    tempPath.reset();
-    pathMeasure.getSegment(
-        newStart,
-        newEnd,
-        tempPath,
-        true);
+      if (newStart >= newEnd) {
+        newStart -= length;
+      }

-    if (newEnd > length) {
-      tempPath2.reset();
-      pathMeasure.getSegment(
-          0,
-          newEnd % length,
-          tempPath2,
-          true);
-      tempPath.addPath(tempPath2);
-    } else if (newStart < 0) {
-      tempPath2.reset();
+      tempPath.reset();
       pathMeasure.getSegment(
-          length + newStart,
-          length,
-          tempPath2,
