           true);
-      tempPath.addPath(tempPath2);
-    }
-    path.set(tempPath);
-    if (L.isTraceEnabled()) {
-      L.endSection("applyTrimPathIfNeeded");
+
+      if (newEnd > length) {
+        tempPath2.reset();
+        pathMeasure.getSegment(
+            0,
+            newEnd % length,
+            tempPath2,
+            true);
+        tempPath.addPath(tempPath2);
+      } else if (newStart < 0) {
+        tempPath2.reset();
+        pathMeasure.getSegment(
+            length + newStart,
+            length,
+            tempPath2,
+            true);
+        tempPath.addPath(tempPath2);
+      }
+      path.set(tempPath);
+    } finally {
+      if (L.isTraceEnabled()) {
+        L.endSection("applyTrimPathIfNeeded");
+      }
     }
   }
